Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label><input id="mirrorTypeInput" type="checkbox" onchange="toggle_mirrorType(this.checked)"> Mirror type: <output id="mirrorTypeVal">Concave mirror</output></label>
<label>Object distance from mirror, in focal lengths: <output id="objectDistanceVal">3</output><input id="objectDistanceInput" type="range" min="0.5" max="5" step="0.1" value="3" oninput="document.getElementById('objectDistanceVal').value=this.value;update_objectDistance(+this.value)"></label>
<span style="font-size:11px">Ray focus: <button id="rayBtn0" onclick="selectRay(0)">All</button> <button id="rayBtn1" onclick="selectRay(1)">1</button> <button id="rayBtn2" onclick="selectRay(2)">2</button> <button id="rayBtn3" onclick="selectRay(3)">3</button> <button id="rayBtn4" onclick="selectRay(4)">4</button></span>
<span id="imageInfo" style="font-size:11px"></span>
<span id="demoNarration" style="margin:0;font-size:10px;max-width:180px"></span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 860, H = 470;
draw.viewbox(0, 0, W, H);

var state = {
  mirrorType: 'concave',
  objectDistance: 3,
  selectedRay: 0,
  currentStep: 0
};

var demoSteps = [
  {
    title: 'Concave mirror: object beyond C',
    narration: 'With the object farther than two focal lengths from a concave mirror, the reflected rays really cross in front of the mirror. The image is real, inverted, and smaller, forming between C and F.',
    state: { mirrorType: 'Concave mirror', objectDistance: 3 }
  },
  {
    title: 'Inspect the four principal-ray rules',
    narration: 'Click rays 1–4 one at a time to see that the construction is built from four simple rules: parallel-to-focus, focus-to-parallel, center-of-curvature return, and symmetric reflection at the vertex.',
    state: { mirrorType: 'Concave mirror', objectDistance: 3 }
  },
  {
    title: 'Concave mirror: object inside F',
    narration: 'Move the object inside the focal length. The reflected rays no longer meet in front of the mirror; their backward extensions meet behind it, producing an upright virtual image.',
    state: { mirrorType: 'Concave mirror', objectDistance: 0.7 }
  },
  {
    title: 'Convex mirror: always virtual',
    narration: 'Switch to the convex mirror. The reflected rays spread apart for every object distance, and only their dashed backward extensions meet behind the mirror, giving a smaller upright virtual image.',
    state: { mirrorType: 'Convex mirror', objectDistance: 3 }
  }
];

var colors = {
  ray1: '#0079a8',
  ray2: '#d83b3b',
  ray3: '#805a9f',
  ray4: '#78a834',
  object: '#d34a55',
  axis: '#666666',
  mirrorBlue: '#bfe3f3',
  mirrorEdge: '#88959b',
  mirrorDark: '#6c777c'
};

var rayRules = {
  1: {
    title: 'Ray 1: parallel ray',
    tip: 'Ray 1 travels from Q parallel to the optical axis.',
    body: 'A ray parallel to the optical axis reflects through F for a concave mirror. For a convex mirror, it reflects as if it came from F behind the mirror, so the backward extension is dashed.'
  },
  2: {
    title: 'Ray 2: focal ray',
    tip: 'Ray 2 uses the focal-point rule and reflects parallel to the axis.',
    body: 'For a concave mirror this ray is associated with F on the object side; after reflection it is parallel to the axis. For a convex mirror it is aimed toward the behind-the-mirror focal point and also reflects parallel to the axis.'
  },
  3: {
    title: 'Ray 3: center-of-curvature ray',
    tip: 'Ray 3 is associated with C and meets the mirror along a normal.',
    body: 'A ray along a radius of curvature meets the spherical mirror normally. It therefore reflects back along the same line, which is why the small square marks the normal-incidence relation.'
  },
  4: {
    title: 'Ray 4: vertex ray',
    tip: 'Ray 4 strikes the vertex V and reflects symmetrically.',
    body: 'At V the mirror normal is the optical axis. The incoming and outgoing angles are equal, so the ray reflects symmetrically about the axis.'
  }
};

function markerFor(color) {
  var m = draw.marker(10, 10, function (add) {
    add.path('M 0 0 L 10 5 L 0 10 z').fill(color).stroke('none');
  });
  m.ref(9, 5);
  m.attr({ orient: 'auto', markerUnits: 'strokeWidth' });
  return m;
}

function textLabel(txt, x, y, anchor, size, fill, family) {
  var t = draw.text(txt);
  t.attr({
    x: x,
    y: y,
    'text-anchor': anchor || 'middle',
    'dominant-baseline': 'middle',
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
  t.font({
    family: family || 'Arial, sans-serif',
    size: size || 17,
    style: family === 'serif' ? 'italic' : 'normal'
  });
  t.fill(fill || '#111111');
  return t;
}

function drawArrow(group, p1, p2, color, width, dash, opacity, marker) {
  if (!p1 || !p2 || !isFinite(p1.x) || !isFinite(p1.y) || !isFinite(p2.x) || !isFinite(p2.y)) return null;
  var ln = group.line(p1.x, p1.y, p2.x, p2.y)
    .stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' })
    .opacity(opacity == null ? 1 : opacity);
  if (dash) ln.attr('stroke-dasharray', dash);
  if (marker) ln.marker('end', marker);
  return ln;
}

function yAtXOnLine(a, b, x) {
  if (!a || !b || Math.abs(b.x - a.x) < 0.0001) return NaN;
  return a.y + (b.y - a.y) * ((x - a.x) / (b.x - a.x));
}

function pointAtMirrorFromLine(q, target, Vx) {
  var y = yAtXOnLine(q, target, Vx);
  if (!isFinite(y)) y = q.y;
  return { x: Vx, y: y };
}

function pointOnLineAtX(a, b, xEnd) {
  var den = b.x - a.x;
  if (!isFinite(den) || Math.abs(den) < 0.0001) return { x: xEnd, y: b.y };
  var t = (xEnd - a.x) / den;
  return { x: xEnd, y: a.y + (b.y - a.y) * t };
}

function reflectedAtVertex(q, V, xEnd) {
  var dx = V.x - q.x;
  if (Math.abs(dx) < 0.0001) return { x: xEnd, y: V.y };
  var slope = (V.y - q.y) / dx;
  return { x: xEnd, y: V.y - slope * (xEnd - V.x) };
}

function drawEye(x, y) {
  var g = draw.group().opacity(0.95);
  g.path('M 0 18 C 25 -12 48 -12 74 18 C 48 30 25 30 0 18 Z')
    .fill('none').stroke({ color: '#111', width: 2 });
  g.circle(12).center(39, 17).fill('none').stroke({ color: '#111', width: 2 });
  g.path('M 57 30 C 72 42 73 60 70 72').fill('none').stroke({ color: '#111', width: 2 });
  g.path('M 46 4 C 55 -3 63 -5 75 -4').fill('none').stroke({ color: '#111', width: 2 });
  g.path('M 31 3 C 35 -6 42 -12 51 -15').fill('none').stroke({ color: '#111', width: 2 });
  g.transform({ translateX: x, translateY: y, scale: 0.72 });
  return g;
}

function drawMirror(Vx, axisY, type) {
  var topY = 62, botY = H - 62;
  var path;
  if (type === 'concave') {
    path = 'M ' + (Vx - 38) + ' ' + topY + ' Q ' + (Vx + 48) + ' ' + axisY + ' ' + (Vx - 38) + ' ' + botY;
  } else {
    path = 'M ' + (Vx + 38) + ' ' + topY + ' Q ' + (Vx - 48) + ' ' + axisY + ' ' + (Vx + 38) + ' ' + botY;
  }

  draw.path(path).fill('none').stroke({ color: colors.mirrorEdge, width: 15, linecap: 'butt' }).opacity(0.88);
  draw.path(path).fill('none').stroke({ color: colors.mirrorBlue, width: 10, linecap: 'butt' });
  draw.path(path).fill('none').stroke({ color: colors.mirrorDark, width: 2, linecap: 'butt' });

  var hatchX = type === 'concave' ? Vx + 41 : Vx - 41;
  for (var yy = topY + 13; yy <= botY - 22; yy += 24) {
    draw.line(hatchX, yy, hatchX + (type === 'concave' ? 13 : -13), yy + 19)
      .stroke({ color: '#8b8b8b', width: 1.2 });
  }
}

function drawArrowObject(base, tip) {
  var m = markerFor(colors.object);
  draw.line(base.x, base.y, tip.x, tip.y)
    .stroke({ color: colors.object, width: 7, linecap: 'round' })
    .marker('end', m);
  draw.circle(8).center(base.x, base.y).fill('#165d89');
  textLabel('P', base.x, base.y + 23, 'middle', 18, '#111', 'serif');
  textLabel('Q', tip.x, tip.y - 18, 'middle', 18, '#111', 'serif');
  textLabel('Object', base.x - 43, (base.y + tip.y) / 2, 'end', 18, '#111');
}

function drawImageArrow(base, tip, virtual) {
  var m = markerFor(colors.object);
  draw.line(base.x, base.y, tip.x, tip.y)
    .stroke({ color: colors.object, width: 6, linecap: 'round' })
    .marker('end', m)
    .opacity(virtual ? 0.9 : 1);
  draw.circle(6).center(base.x, base.y).fill(colors.object).opacity(0.92);
  textLabel('P′', base.x, base.y + (tip.y < base.y ? 24 : -20), 'middle', 17, '#111', 'serif');
  textLabel('Q′', tip.x + 7, tip.y + (tip.y < base.y ? -15 : 15), 'start', 17, '#111', 'serif');
  var labY = base.y + (tip.y < base.y ? 56 : -48);
  if (labY < 28) labY = base.y + 45;
  if (labY > H - 25) labY = base.y - 45;
  textLabel('Image', base.x + 38, labY, 'start', 18, '#111');
}

function drawRightAngle(mPoint, cPoint, opacity) {
  if (!mPoint || !cPoint || !isFinite(mPoint.y) || mPoint.y < 36 || mPoint.y > H - 36) return;
  var ux = cPoint.x - mPoint.x, uy = cPoint.y - mPoint.y;
  var len = Math.sqrt(ux * ux + uy * uy);
  if (len < 0.001) return;
  ux /= len; uy /= len;
  var tx = -uy, ty = ux, s = 17;
  var p1 = { x: mPoint.x + ux * s, y: mPoint.y + uy * s };
  var p2 = { x: p1.x + tx * s, y: p1.y + ty * s };
  var p3 = { x: mPoint.x + tx * s, y: mPoint.y + ty * s };
  draw.polyline([[p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y]])
    .fill('none').stroke({ color: '#333', width: 1.5 }).opacity(opacity);
}

function renderRay(id, q, mPoint, qImage, opts, markers) {
  var selected = state.selectedRay === 0 || state.selectedRay === id;
  var opacity = selected ? 1 : 0.16;
  var extOpacity = selected ? 0.70 : 0.10;
  var color = opts.color;
  var g = draw.group();
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) { showTooltip(rayRules[id].tip, e); });
  g.on('mouseleave', function () { hideTooltip(); });
  g.on('click', function () {
    selectRay(id);
    showPopup(rayRules[id].title, rayRules[id].body);
  });

  drawArrow(g, q, mPoint, color, 2.35, null, opacity, markers[color]);

  var endPoint;
  if (opts.noImage) {
    if (id === 2) endPoint = { x: 66, y: mPoint.y };
    else if (id === 4) endPoint = reflectedAtVertex(q, mPoint, 66);
    else endPoint = pointOnLineAtX(mPoint, opts.guidePoint, 66);
  } else if (opts.real) {
    endPoint = pointOnLineAtX(mPoint, qImage, 66);
  } else {
    endPoint = pointOnLineAtX(mPoint, qImage, 66);
  }

  drawArrow(g, mPoint, endPoint, color, 2.35, null, opacity, markers[color]);

  if (opts.virtual && !opts.noImage && qImage) {
    drawArrow(g, mPoint, qImage, color, 1.8, '7 6', extOpacity, null);
  }

  var lx = (q.x + mPoint.x) / 2;
  var ly = (q.y + mPoint.y) / 2;
  if (id === 1) { ly -= 18; lx += 5; }
  if (id === 2) { ly -= 18; }
  if (id === 3) { ly += 16; }
  if (id === 4) { ly += 24; lx -= 8; }
  var n = textLabel(String(id), lx, ly, 'middle', 16, color);
  n.opacity(opacity);

  return g;
}

function render() {
  draw.clear();

  var markers = {};
  markers[colors.ray1] = markerFor(colors.ray1);
  markers[colors.ray2] = markerFor(colors.ray2);
  markers[colors.ray3] = markerFor(colors.ray3);
  markers[colors.ray4] = markerFor(colors.ray4);

  var axisY = 235;
  var Vx = 620;
  var f = 95;
  var hObj = 58;
  var type = state.mirrorType;
  var doDist = state.objectDistance * f;
  var fSigned = type === 'concave' ? f : -f;
  var denom = 1 / fSigned - 1 / doDist;
  var noImage = type === 'concave' && Math.abs(denom) < 0.0009;
  var di = noImage ? Infinity : 1 / denom;
  var mag = noImage ? Infinity : -di / doDist;

  var objX = Vx - doDist;
  if (objX < 72) objX = 72;
  var actualDo = Vx - objX;
  if (actualDo !== doDist) {
    denom = 1 / fSigned - 1 / actualDo;
    noImage = type === 'concave' && Math.abs(denom) < 0.0009;
    di = noImage ? Infinity : 1 / denom;
    mag = noImage ? Infinity : -di / actualDo;
  }

  var base = { x: objX, y: axisY };
  var q = { x: objX, y: axisY - hObj };

  var Fp = { x: type === 'concave' ? Vx - f : Vx + f, y: axisY };
  var Cp = { x: type === 'concave' ? Vx - 2 * f : Vx + 2 * f, y: axisY };
  var V = { x: Vx, y: axisY };

  var imageBase = noImage ? null : { x: Vx - di, y: axisY };
  var qImage = noImage ? null : { x: Vx - di, y: axisY - mag * hObj };
  var isVirtual = !noImage && di < 0;
  var isReal = !noImage && di > 0;

  draw.line(45, axisY, W - 40, axisY).stroke({ color: colors.axis, width: 1.5 });
  drawMirror(Vx, axisY, type);

  draw.circle(6).center(Fp.x, Fp.y).fill('#222');
  draw.circle(6).center(Cp.x, Cp.y).fill('#222');

  drawEye(150, axisY + 100);

  var M1 = { x: Vx, y: q.y };
  var M2 = pointAtMirrorFromLine(q, Fp, Vx);
  var M3 = pointAtMirrorFromLine(q, Cp, Vx);
  var M4 = V;

  var guideForNoImage = type === 'concave' ? Fp : { x: Vx + f, y: axisY };
  var rayOpts = {
    real: isReal,
    virtual: isVirtual || type === 'convex',
    noImage: noImage,
    guidePoint: guideForNoImage
  };

  renderRay(1, q, M1, qImage || Fp, Object.assign({}, rayOpts, { color: colors.ray1 }), markers);
  renderRay(2, q, M2, qImage || { x: 66, y: M2.y }, Object.assign({}, rayOpts, { color: colors.ray2 }), markers);
  renderRay(3, q, M3, qImage || Cp, Object.assign({}, rayOpts, { color: colors.ray3 }), markers);
  renderRay(4, q, M4, qImage || reflectedAtVertex(q, V, 66), Object.assign({}, rayOpts, { color: colors.ray4 }), markers);

  drawRightAngle(M3, Cp, state.selectedRay === 0 || state.selectedRay === 3 ? 0.9 : 0.18);

  drawArrowObject(base, q);

  if (!noImage && imageBase.x > 35 && imageBase.x < W + 60 && qImage.y > -130 && qImage.y < H + 130) {
    drawImageArrow(imageBase, qImage, isVirtual);
  }

  textLabel('V', Vx + (type === 'concave' ? 22 : -22), axisY + 23, 'middle', 18, '#111', 'serif');
  textLabel('F', Fp.x, axisY + (type === 'concave' ? -22 : 22), 'middle', 18, '#111', 'serif');
  textLabel('C', Math.min(W - 25, Math.max(25, Cp.x)), axisY + (type === 'concave' ? -22 : 22), 'middle', 18, '#111', 'serif');
  textLabel(type === 'concave' ? '(a)' : '(b)', W / 2, H - 22, 'middle', 18, '#111');

  var info = document.getElementById('imageInfo');
  if (info) {
    if (noImage) {
      info.textContent = 'Image: at infinity; reflected rays are parallel.';
    } else if (isReal) {
      info.textContent = 'Image: real, inverted, where solid reflected rays meet.';
    } else {
      info.textContent = 'Image: virtual, upright, where dashed backward extensions meet.';
    }
  }

  updateRayButtons();
}

function updateRayButtons() {
  for (var i = 0; i <= 4; i++) {
    var b = document.getElementById('rayBtn' + i);
    if (b) {
      if (state.selectedRay === i) b.classList.add('active');
      else b.classList.remove('active');
    }
  }
}

function selectRay(n) {
  state.selectedRay = n;
  render();
}

function toggle_mirrorType(on) {
  state.mirrorType = on ? 'convex' : 'concave';
  var out = document.getElementById('mirrorTypeVal');
  if (out) out.value = on ? 'Convex mirror' : 'Concave mirror';
  render();
}

function update_objectDistance(v) {
  state.objectDistance = v;
