  },
  {
    title: 'Concave mirror: object inside F',
    narration: 'Move the object inside the focal length. The reflected rays diverge, but their dashed backward extensions meet behind the mirror, producing an upright virtual image.',
    state: { mirrorType: 'Concave mirror', objectDistance: 0.7 }
  },
  {
    title: 'Convex mirror: always virtual',
    narration: 'Switch to the convex mirror. The reflected rays spread apart for every object distance, and only their dashed backward extensions meet behind the mirror, giving a smaller upright virtual image.',
    state: { mirrorType: 'Convex mirror', objectDistance: 3 }
  }
];

var colors = {
  ray1: '#007fae',
  ray2: '#d83b3b',
  ray3: '#805a9f',
  ray4: '#78a834',
  object: '#d34a55',
  axis: '#5b5b5b',
  mirrorBlue: '#bfe3f3',
  mirrorEdge: '#899aa1',
  mirrorDark: '#63737a'
};

var rayRules = {
  1: {
    title: 'Ray 1: parallel ray',
    tip: 'Ray 1 leaves Q parallel to the optical axis.',
    body: 'A ray parallel to the optical axis reflects through the focal point for a concave mirror. For a convex mirror it reflects as if it came from the focal point behind the mirror, so the apparent part is dashed.'
  },
  2: {
    title: 'Ray 2: focal ray',
    tip: 'Ray 2 uses the focal-point rule.',
    body: 'The ray associated with F reflects parallel to the optical axis. In the virtual-image cases, the solid reflected ray is still what light actually follows; the dashed part is only the backward extension.'
  },
  3: {
    title: 'Ray 3: center-of-curvature ray',
    tip: 'Ray 3 is associated with C and meets the mirror along a normal.',
    body: 'A ray along a radius of curvature strikes the spherical mirror normally. It therefore retraces the same line after reflection.'
  },
  4: {
    title: 'Ray 4: vertex ray',
    tip: 'Ray 4 strikes the vertex V.',
    body: 'At the vertex, the normal is the optical axis. The incoming and outgoing angles are equal, so the ray reflects symmetrically about the axis.'
  }
};

function markerFor(color, scale) {
  var s = scale || 1;
  var m = draw.marker(9 * s, 9 * s, function (add) {
    add.path('M 0 0 L ' + (9 * s) + ' ' + (4.5 * s) + ' L 0 ' + (9 * s) + ' z').fill(color).stroke('none');
  });
  m.ref(8.1 * s, 4.5 * s);
  m.attr({ orient: 'auto', markerUnits: 'strokeWidth' });
  return m;
}

function textLabel(txt, x, y, anchor, size, fill, family) {
  var t = draw.text(txt);
  t.attr({
    x: x,
    y: y,
    'text-anchor': anchor || 'middle',
    'dominant-baseline': 'middle',
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4.2,
    'stroke-linejoin': 'round'
  });
  t.font({
    family: family === 'serif' ? 'Times New Roman, serif' : 'Arial, sans-serif',
    size: size || 18,
    style: family === 'serif' ? 'italic' : 'normal'
  });
  t.fill(fill || '#111');
  return t;
}

function drawArrow(group, p1, p2, color, width, dash, opacity, marker) {
  if (!p1 || !p2 || !isFinite(p1.x) || !isFinite(p1.y) || !isFinite(p2.x) || !isFinite(p2.y)) return null;
  var ln = group.line(p1.x, p1.y, p2.x, p2.y)
    .stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' })
    .opacity(opacity == null ? 1 : opacity);
  if (dash) ln.attr('stroke-dasharray', dash);
  if (marker) ln.marker('end', marker);
  return ln;
}

function addSmallDirectionArrow(group, a, b, t, color, opacity, marker) {
  var x = a.x + (b.x - a.x) * t;
  var y = a.y + (b.y - a.y) * t;
  var vx = b.x - a.x, vy = b.y - a.y;
  var len = Math.sqrt(vx * vx + vy * vy);
  if (len < 0.1) return;
  vx /= len; vy /= len;
  drawArrow(group, { x: x - vx * 13, y: y - vy * 13 }, { x: x + vx * 13, y: y + vy * 13 }, color, 2.1, null, opacity, marker);
}

function yAtXOnLine(a, b, x) {
  if (!a || !b || Math.abs(b.x - a.x) < 0.0001) return NaN;
  return a.y + (b.y - a.y) * ((x - a.x) / (b.x - a.x));
}

function pointAtMirrorFromLine(q, target, Vx) {
  var y = yAtXOnLine(q, target, Vx);
  if (!isFinite(y)) y = q.y;
  return { x: Vx, y: y };
}

function pointOnLineAtX(a, b, xEnd) {
  if (!a || !b) return null;
  var den = b.x - a.x;
  if (!isFinite(den) || Math.abs(den) < 0.0001) return { x: xEnd, y: b.y };
  return { x: xEnd, y: a.y + (b.y - a.y) * ((xEnd - a.x) / den) };
}

function reflectedAtVertex(q, V, xEnd) {
  var dx = V.x - q.x;
  if (Math.abs(dx) < 0.0001) return { x: xEnd, y: V.y };
  var slope = (V.y - q.y) / dx;
  return { x: xEnd, y: V.y - slope * (xEnd - V.x) };
}

function drawEye(x, y) {
  var g = draw.group().opacity(0.96);
  g.path('M 0 20 C 22 -10 53 -10 76 20 C 53 33 23 33 0 20 Z')
    .fill('none').stroke({ color: '#111', width: 2.2 });
  g.circle(12).center(39, 19).fill('none').stroke({ color: '#111', width: 2.1 });
  g.circle(3.2).center(39, 19).fill('#111');
  g.path('M 57 30 C 73 42 74 62 70 75').fill('none').stroke({ color: '#111', width: 2.1 });
  g.path('M 43 5 C 52 -2 63 -5 75 -3').fill('none').stroke({ color: '#111', width: 2.1 });
  g.path('M 30 4 C 34 -6 42 -12 51 -16').fill('none').stroke({ color: '#111', width: 2.1 });
  g.transform({ translateX: x, translateY: y, scale: 0.78 });
  return g;
}

function drawMirror(Vx, axisY, type, mirrorHeight) {
  var topY = axisY - mirrorHeight / 2;
  var botY = axisY + mirrorHeight / 2;
  var path;
  if (type === 'concave') {
    path = 'M ' + (Vx - 42) + ' ' + topY + ' Q ' + (Vx + 46) + ' ' + axisY + ' ' + (Vx - 42) + ' ' + botY;
  } else {
    path = 'M ' + (Vx + 42) + ' ' + topY + ' Q ' + (Vx - 46) + ' ' + axisY + ' ' + (Vx + 42) + ' ' + botY;
  }

  draw.path(path).fill('none').stroke({ color: colors.mirrorEdge, width: 16, linecap: 'butt' }).opacity(0.95);
  draw.path(path).fill('none').stroke({ color: colors.mirrorBlue, width: 11, linecap: 'butt' });
  draw.path(path).fill('none').stroke({ color: colors.mirrorDark, width: 2, linecap: 'butt' });

  var hatchX = type === 'concave' ? Vx + 45 : Vx - 45;
  for (var yy = topY + 20; yy <= botY - 28; yy += 27) {
    draw.line(hatchX, yy, hatchX + (type === 'concave' ? 14 : -14), yy + 22)
      .stroke({ color: '#8b8b8b', width: 1.15 });
  }
}

function drawThinRedArrow(base, tip, virtual) {
  var up = tip.y < base.y;
  var headLen = 16;
  var headWid = 15;
  var shaftEnd = { x: tip.x, y: tip.y + (up ? headLen : -headLen) };
  draw.line(base.x, base.y, shaftEnd.x, shaftEnd.y)
    .stroke({ color: colors.object, width: 6, linecap: 'butt' })
    .opacity(virtual ? 0.9 : 1);
  var p = up
    ? [[tip.x, tip.y], [tip.x - headWid / 2, tip.y + headLen], [tip.x + headWid / 2, tip.y + headLen]]
    : [[tip.x, tip.y], [tip.x - headWid / 2, tip.y - headLen], [tip.x + headWid / 2, tip.y - headLen]];
  draw.polygon(p).fill(colors.object).opacity(virtual ? 0.9 : 1);
}

function drawArrowObject(base, tip) {
  drawThinRedArrow(base, tip, false);
  draw.circle(7.2).center(base.x, base.y).fill('#165d89');
  textLabel('P', base.x, base.y + 22, 'middle', 19, '#111', 'serif');
  textLabel('Q', tip.x, tip.y - 20, 'middle', 19, '#111', 'serif');
  textLabel('Object', base.x - 32, (base.y + tip.y) / 2, 'end', 18, '#111');
}

function drawImageArrow(base, tip, virtual) {
  drawThinRedArrow(base, tip, virtual);
  draw.circle(5.4).center(base.x, base.y).fill(colors.object).opacity(0.92);

  var upright = tip.y < base.y;
  if (upright) {
    textLabel('P′', base.x + 14, base.y + 18, 'start', 18, '#111', 'serif');
    textLabel('Q′', tip.x + 13, tip.y - 14, 'start', 18, '#111', 'serif');
    textLabel('Image', base.x + 34, Math.min(base.y + 62, H - 34), 'start', 18, '#111');
  } else {
    textLabel('P′', base.x + 11, base.y - 18, 'start', 18, '#111', 'serif');
    textLabel('Q′', tip.x + 12, tip.y + 17, 'start', 18, '#111', 'serif');
    textLabel('Image', base.x + 42, tip.y + 62, 'start', 18, '#111');
  }
}

function drawRightAngle(mPoint, cPoint, opacity) {
  if (!mPoint || !cPoint || !isFinite(mPoint.y) || mPoint.y < 34 || mPoint.y > H - 34) return;
  var ux = cPoint.x - mPoint.x, uy = cPoint.y - mPoint.y;
  var len = Math.sqrt(ux * ux + uy * uy);
  if (len < 0.001) return;
  ux /= len; uy /= len;
  var tx = -uy, ty = ux, s = 16;
  var p1 = { x: mPoint.x + ux * s, y: mPoint.y + uy * s };
  var p2 = { x: p1.x + tx * s, y: p1.y + ty * s };
  var p3 = { x: mPoint.x + tx * s, y: mPoint.y + ty * s };
  draw.polyline([[p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y]])
    .fill('none').stroke({ color: '#222', width: 1.5 }).opacity(opacity);
}

function rayLabel(id, x, y, color, opacity) {
  textLabel(String(id), x, y, 'middle', 16, color).opacity(opacity);
}

function renderRay(id, q, mPoint, qImage, opts, markers) {
  var selected = state.selectedRay === 0 || state.selectedRay === id;
  var opacity = selected ? 1 : 0.15;
  var extOpacity = selected ? 0.72 : 0.11;
  var color = opts.color;
  var g = draw.group();
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) { showTooltip(rayRules[id].tip, e); });
  g.on('mouseleave', function () { hideTooltip(); });
  g.on('click', function () {
    selectRay(id);
    showPopup(rayRules[id].title, rayRules[id].body);
  });

  var incidentEnd = mPoint;
  if (id === 3 && opts.type === 'convex') incidentEnd = mPoint;
  drawArrow(g, q, incidentEnd, color, 2.15, null, opacity, markers[color]);

  var leftX = opts.type === 'concave' ? 55 : 70;
  var solidEnd;
  if (opts.noImage) {
    if (id === 2) solidEnd = { x: leftX, y: mPoint.y };
    else if (id === 4) solidEnd = reflectedAtVertex(q, mPoint, leftX);
    else solidEnd = pointOnLineAtX(mPoint, opts.guidePoint, leftX);
  } else if (opts.virtual) {
    if (id === 2) solidEnd = { x: leftX, y: mPoint.y };
    else solidEnd = pointOnLineAtX(mPoint, qImage, leftX);
  } else {
    solidEnd = pointOnLineAtX(mPoint, qImage, leftX);
  }
  drawArrow(g, mPoint, solidEnd, color, 2.15, null, opacity, markers[color]);

  if (opts.virtual && !opts.noImage && qImage) {
    drawArrow(g, mPoint, qImage, color, 1.75, '7 6', extOpacity, null);
  }

  addSmallDirectionArrow(g, q, mPoint, 0.55, color, opacity, markers[color]);
  if (solidEnd) addSmallDirectionArrow(g, mPoint, solidEnd, 0.55, color, opacity, markers[color]);

  var incX = q.x + (mPoint.x - q.x) * (id === 1 ? 0.55 : 0.47);
  var incY = q.y + (mPoint.y - q.y) * (id === 1 ? 0.55 : 0.47);
  if (id === 1) incY -= 16;
  if (id === 2) { incX += 8; incY -= 16; }
  if (id === 3) { incX += 7; incY -= 14; }
  if (id === 4) { incX += 10; incY -= 14; }
  rayLabel(id, incX, incY, color, opacity);

  if (solidEnd) {
    var t = opts.virtual ? 0.40 : 0.47;
    var lx = mPoint.x + (solidEnd.x - mPoint.x) * t;
    var ly = mPoint.y + (solidEnd.y - mPoint.y) * t;
    if (id === 1) { lx -= 8; ly += 17; }
    if (id === 2) { lx -= 12; ly -= 16; }
    if (id === 3) { lx += 8; ly -= 18; }
    if (id === 4) { lx -= 10; ly += 18; }
    rayLabel(id, lx, ly, color, opacity);
  }

  return g;
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function layoutForState() {
  var type = state.mirrorType;
  var d = state.objectDistance;
  if (type === 'convex') {
    return { axisY: 270, Vx: 455, f: 115, mirrorHeight: 330, hObj: 118, leftEnd: 52 };
  }
  if (d < 1) {
    return { axisY: 292, Vx: 610, f: 105, mirrorHeight: 385, hObj: 96, leftEnd: 52 };
  }
  return { axisY: 238, Vx: 760, f: 190, mirrorHeight: 445, hObj: 122, leftEnd: 52 };
}

function render() {
  draw.clear();

  var markers = {};
  markers[colors.ray1] = markerFor(colors.ray1, 0.9);
  markers[colors.ray2] = markerFor(colors.ray2, 0.9);
  markers[colors.ray3] = markerFor(colors.ray3, 0.9);
  markers[colors.ray4] = markerFor(colors.ray4, 0.9);

  var lay = layoutForState();
  var axisY = lay.axisY;
  var Vx = lay.Vx;
  var f = lay.f;
  var hObj = lay.hObj;
  var type = state.mirrorType;
  var doDist = state.objectDistance * f;
  var fSigned = type === 'concave' ? f : -f;

  var objX = Vx - doDist;
  if (objX < 74) {
    objX = 74;
    doDist = Vx - objX;
  }
  if (objX > Vx - 42) {
    objX = Vx - 42;
    doDist = Vx - objX;
  }

  var denom = 1 / fSigned - 1 / doDist;
  var noImage = type === 'concave' && Math.abs(denom) < 0.0009;
  var di = noImage ? Infinity : 1 / denom;
  var mag = noImage ? Infinity : -di / doDist;

  var base = { x: objX, y: axisY };
  var q = { x: objX, y: axisY - hObj };

  var Fp = { x: type === 'concave' ? Vx - f : Vx + f, y: axisY };
  var Cp = { x: type === 'concave' ? Vx - 2 * f : Vx + 2 * f, y: axisY };
  var V = { x: Vx, y: axisY };

  var imageBase = null, qImage = null;
  if (!noImage) {
    imageBase = { x: Vx - di, y: axisY };
    qImage = { x: Vx - di, y: axisY - mag * hObj };
    if (type === 'concave' && state.objectDistance < 1) {
      var maxBehind = W - 42;
      if (imageBase.x > maxBehind) {
        var scaleBack = (maxBehind - Vx) / (imageBase.x - Vx);
        imageBase.x = maxBehind;
        qImage.x = maxBehind;
        qImage.y = axisY + (qImage.y - axisY) * scaleBack;
      }
      if (qImage.y < 32) qImage.y = 32;
    }
  }
  var isVirtual = !noImage && di < 0;
  var isReal = !noImage && di > 0;

  draw.line(52, axisY, W - 42, axisY).stroke({ color: colors.axis, width: 1.45 });
  drawMirror(Vx, axisY, type, lay.mirrorHeight);

  draw.circle(5.7).center(Fp.x, Fp.y).fill('#111');
  draw.circle(5.7).center(clamp(Cp.x, 25, W - 25), Cp.y).fill('#111');

  drawEye(type === 'concave' ? 260 : 95, axisY + 88);

  var M1 = { x: Vx, y: q.y };
  var M2 = pointAtMirrorFromLine(q, Fp, Vx);
  var M3 = pointAtMirrorFromLine(q, Cp, Vx);
  var M4 = V;

  var guideForNoImage = type === 'concave' ? Fp : { x: Vx + f, y: axisY };
  var rayOpts = {
    type: type,
    real: isReal,
    virtual: isVirtual || type === 'convex',
    noImage: noImage,
    guidePoint: guideForNoImage
  };

  renderRay(1, q, M1, qImage || Fp, Object.assign({}, rayOpts, { color: colors.ray1 }), markers);
  renderRay(2, q, M2, qImage || { x: lay.leftEnd, y: M2.y }, Object.assign({}, rayOpts, { color: colors.ray2 }), markers);
  renderRay(3, q, M3, qImage || Cp, Object.assign({}, rayOpts, { color: colors.ray3 }), markers);
  renderRay(4, q, M4, qImage || reflectedAtVertex(q, V, lay.leftEnd), Object.assign({}, rayOpts, { color: colors.ray4 }), markers);

  drawRightAngle(M3, Cp, state.selectedRay === 0 || state.selectedRay === 3 ? 0.88 : 0.16);

  drawArrowObject(base, q);

  if (!noImage && imageBase.x > 30 && imageBase.x < W + 10 && qImage.y > -20 && qImage.y < H + 20) {
    drawImageArrow(imageBase, qImage, isVirtual);
  }

  textLabel('V', Vx + (type === 'concave' ? 24 : -20), axisY + 22, 'middle', 19, '#111', 'serif');
  textLabel('F', Fp.x, axisY + (type === 'concave' ? -22 : 23), 'middle', 19, '#111', 'serif');
  textLabel('C', clamp(Cp.x, 25, W - 25), axisY + (type === 'concave' ? -23 : 23), 'middle', 19, '#111', 'serif');
  textLabel(type === 'concave' ? '(a)' : '(b)', W / 2, H - 24, 'middle', 19, '#111');

  var info = document.getElementById('imageInfo');
  if (info) {
    if (noImage) {
      info.textContent = 'Image: at infinity; reflected rays are parallel.';
    } else if (isReal) {
      info.textContent = 'Image: real, inverted, where solid reflected rays meet.';
    } else {
      info.textContent = 'Image: virtual, upright, where dashed backward extensions meet.';
    }
  }

  updateRayButtons();
}

function updateRayButtons() {
  for (var i = 0; i <= 4; i++) {
    var b = document.getElementById('rayBtn' + i);
    if (b) {
      if (state.selectedRay === i) b.classList.add('active');
      else b.classList.remove('active');
    }
  }
}

function selectRay(n) {
  state.selectedRay = n;
  render();
}

function toggle_mirrorType(on) {
  state.mirrorType = on ? 'convex' : 'concave';
  var out = document.getElementById('mirrorTypeVal');
  if (out) out.value = on ? 'Convex mirror' : 'Concave mirror';
  render();
}

function update_objectDistance(v) {
  state.objectDistance = v;
  render();
}

function applyStep(i) {
  state.currentStep = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.currentStep];
  var isConvex = step.state.mirrorType === 'Convex mirror';

  var cb = document.getElementById('mirrorTypeInput');
  if (cb) cb.checked = isConvex;

  var out = document.getElementById('mirrorTypeVal');
  if (out) out.value = isConvex ? 'Convex mirror' : 'Concave mirror';

  var slider = document.getElementById('objectDistanceInput');
  var val = document.getElementById('objectDistanceVal');
  if (slider) slider.value = step.state.objectDistance;
  if (val) val.value = step.state.objectDistance;

  state.mirrorType = isConvex ? 'convex' : 'concave';
  state.objectDistance = step.state.objectDistance;
  state.selectedRay = 0;

  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (state.currentStep + 1) + '/' + demoSteps.length + ' ' + step.title;

  var nar = document.getElementById('demoNarration');
  if (nar) nar.textContent = step.narration;

  render();
}

function nextStep() {
  applyStep(state.currentStep + 1);
}

function prevStep() {
  applyStep(state.currentStep - 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

